export type Exclusion = 
/**
 * GMS, GSF, Play Store, WebView…: tied to the device or broken if copied.
 */
{ kind: "fixedList" } | 
/**
 * Shares a system UID (`android.uid.*`).
 */
{ kind: "systemSharedUser"; sharedUser: string }
export type FieldKind = "phone" | "email" | "address" | "organization" | "website" | "nickname" | "event" | "im" | "relation" | "sip" | "note"
export type FileEntry = { path: string; size: number; sha256: string }
export type FileProblem = { path: string; problem: Problem }
export type Folder = { 
/**
 * Name in /data/media/0; "" stands for the loose files at the top.
 */
name: string; size: number }
export type ItemError = { package: string | null; 
/**
 * What failed, e.g. `apk:base.apk`, `data:ce`, `forceStop`.
 */
step: string; error: CoreError }
export type ItemStatus = "pending" | "running" | "done" | 
/**
 * Finished with some failed steps.
 */
"error"
export type JobEvent = { kind: "started"; totalBytes: number; packages: string[] } | { kind: "item"; package: string; status: ItemStatus } | { kind: "progress"; bytesDone: number; totalBytes: number; package: string; step: string; speed: number } | { kind: "packing" } | 
/**
 * Waiting for the phone to come back or be unlocked; the step in progress is retried.
 */
{ kind: "paused"; reason: PauseReason } | { kind: "resumed" } | { kind: "finished"; result: JobResult } | 
/**
 * The job could not run or finish at all (e.g. the folder could not be created).
 */
{ kind: "failed"; error: CoreError }
/**
 * Backup or restore progress.
 */
export type JobProgressEvent = JobEvent
export type JobResult = { 
/**
 * The backup folder, or the `.adbkeep` file when packed.
 */
path: string; cancelled: boolean; errors: ItemError[]; 
/**
 * Bytes received from the phone.
 */
bytes: number; 
/**
 * Bytes on the PC.
 */
sizeOnDisk: number; durationMs: number; 
/**
 * Per-app outcome of a restore; empty for backups.
 */
restored: RestoredApp[]; 
/**
 * Per-item outcome of the Resto tab in a restore; empty for backups.
 */
other: OtherOutcome[] }
export type LocalCalendar = { id: number; name: string; events: number }
export type LogEntry = { id: number; 
/**
 * Unix time in milliseconds.
 */
startedAt: number; durationMs: number; program: string; args: string[]; exitCode: number | null; stdout: string; stderr: string; 
/**
 * Bytes of stdout when it was binary and streamed elsewhere instead of captured.
 */
streamedBytes: number | null; 
/**
 * Which job ran it (e.g. a backup), so its own session log leaves out other commands.
 */
tag: string | null }
/**
 * A command was run (advanced-mode log panel).
 */
export type LogEvent = LogEntry
export type Manifest = { formatVersion: number; appVersion: string; 
/**
 * RFC 3339, UTC.
 */
createdAt: string; name: string; source: SourceDevice; apps: ManifestApp[]; 
/**
 * Accounts to sign in again on the target (point 17); names and types only.
 */
accounts: Account[]; 
/**
 * Apps with Android Keystore keys (point 18).
 */
keystorePackages: string[]; 
/**
 * Resto tab items (messages, contacts, Wi-Fi, files…).
 */
other?: OtherEntry[]; files: FileEntry[]; errors: ItemError[]; 
/**
 * False when the backup was cancelled or the phone went away.
 */
complete: boolean }
export type ManifestApp = { package: string; 
/**
 * Name shown on the phone, when the helper provided it.
 */
label?: string | null; kind: AppKind; versionCode: number; versionName: string | null; 
/**
 * `apps/<pkg>/meta.json`: the full analysis of the app (`AppInfo`).
 */
meta: string; 
/**
 * Relative paths of the APKs; empty when only data was saved.
 */
apks: string[]; data: DataArchive[]; permissions: boolean }
export type Message = { mms: boolean; 
/**
 * Milliseconds since the epoch.
 */
date: number; outgoing: boolean; 
/**
 * Sender in group MMS.
 */
from: string | null; body: string; attachments: Attachment[] }
/**
 * What the Resto tab shows before backing up: counts and sizes.
 */
export type OtherAnalysis = { sms: number | null; mms: number | null; threads: number | null; contacts: ContactAccount[]; calls: number | null; blocked: number | null; calendars: LocalCalendar[]; dictionary: number | null; wifiNetworks: number | null; wifiPath: string | null; settings: SettingEntry[]; notificationPolicy: boolean; 
/**
 * Ringtones, Notifications and Alarms folders, bytes.
 */
soundsSize: number; wallpaperFiles: string[]; certificates: number; folders: Folder[]; 
/**
 * Provider databases found (advanced): which copy, CE or DE, has data.
 */
databases: DbLocation[] }
export type OtherCompat = { item: OtherItem; status: CompatStatus; reasons: OtherReason[]; count: number | null }
/**
 * What the backup holds for one item.
 */
export type OtherEntry = { item: OtherItem; files: string[]; 
/**
 * Rows, networks, files… depending on the item.
 */
count: number | null }
export type OtherItem = "sms" | "contacts" | "calls" | "blocked" | "calendar" | "wifi" | "settings" | "notifications" | "sounds" | "wallpaper" | "dictionary" | "certificates" | "files"
/**
 * Outcome of one item.
 */
export type OtherOutcome = { item: OtherItem; done: number; failed: number; errors: string[] }
export type OtherReason = 
/**
 * ⛔ The backup has nothing of this item.
 */
{ kind: "empty" } | 
/**
 * ⛔ Read and written through the helper, which is off.
 */
{ kind: "helperRequired" } | 
/**
 * ⛔ Not restored yet; the backup keeps it for reference.
 */
{ kind: "notSupported" } | 
/**
 * ⚠️ The backup has MMS, which are not restored yet; only the SMS are.
 */
{ kind: "mmsNotRestored" } | 
/**
 * ⛔ `cmd wifi add-network` needs Android 11.
 */
{ kind: "wifiNeedsAndroid11" } | 
/**
 * ⚠️ Enterprise networks (and some others) cannot be recreated and are skipped.
 */
{ kind: "wifiSkipped"; count: number } | 
/**
 * ⚠️ The image is copied to the phone; setting it as wallpaper is done by hand.
 */
{ kind: "wallpaperManual" } | 
/**
 * ⛔ The backup has no wallpaper image (a built-in or live wallpaper was in use).
 */
{ kind: "noWallpaperImage" } | 
/**
 * ⚠️ Without Android 11 the new files appear after restarting the phone.
 */
{ kind: "scanAfterRestart" }
export type OtherRestoreSelection = { sms: boolean; contacts: boolean; 
/**
 * Copy the .vcf to the phone and open it in the Contacts app instead of inserting.
 */
contactsAsVcf: boolean; calls: boolean; blocked: boolean; calendar: boolean; dictionary: boolean; wifi: boolean; 
/**
 * "table/key" settings to write.
 */
settings: string[]; sounds: boolean; wallpaper: boolean; certificates: boolean; folders: string[] }
export type OtherSelection = { sms: boolean; 
/**
 * Contact account types to save ("" = on the phone); empty saves no contacts.
 */
contacts: string[]; calls: boolean; blocked: boolean; calendar: boolean; wifi: boolean; 
/**
 * Settings to restore later, as "table/key". All settings are saved for reference;
 * `None` saves none.
 */
settings: string[] | null; notifications: boolean; sounds: boolean; wallpaper: boolean; dictionary: boolean; certificates: boolean; 
/**
 * Folders of shared storage ("" = loose files at the top).
 */
folders: string[]; 
/**
 * `tar --exclude` patterns for the folders (default `.thumbnails`).
 */
exclude: string[] }
export type PartData = { mime: string; base64: string }
export type PauseReason = 
/**
 * Unplugged, unauthorized or still reconnecting (probing, root prompt).
 */
"disconnected" | 
/**
 * Restarted and not unlocked since: app data (CE) cannot be read or written.
 */
"locked"
export type Permissions = { 
/**
 * Granted runtime permissions.
 */
runtime: string[]; appOps: AppOp[]; special: SpecialAccess[]; 
/**
 * Default-app roles held, e.g. `android.app.role.BROWSER`.
 */
roles: string[] }
export type PlannedAction = "install" | "update" | 
/**
 * Installed with the same or a newer version: only data and permissions.
 */
"dataOnly" | "skip"
export type PreviewApp = { meta: AppInfo; compat: AppCompat }
export type Problem = { kind: "missing" } | { kind: "sizeMismatch"; expected: number; actual: number } | { kind: "hashMismatch" } | 
/**
 * The compressed tar cannot be read to the end.
 */
{ kind: "corrupt"; reason: string } | 
/**
 * In the backup but not in the manifest.
 */
{ kind: "unexpected" }
export type Reason = 
/**
 * ⛔ `minSdk` above the target's SDK.
 */
{ kind: "minSdkTooHigh"; minSdk: number; targetSdk: number } | 
/**
 * ⛔ Android 14+ blocks apps targeting SDK < 23 (unless forced, unverified).
 */
{ kind: "targetSdkTooLow"; appTargetSdk: number } | 
/**
 * ⛔ Native code for a processor type the target lacks.
 */
{ kind: "abiMismatch"; appAbi: string; deviceAbis: string[] } | 
/**
 * ⛔ Installed on the target with another signature.
 */
{ kind: "signatureMismatch" } | 
/**
 * ⛔ The backup has no APK and the app is not installed on the target.
 */
{ kind: "noApk" } | 
/**
 * ⚠️ A system app being installed as a normal app: may not fully work.
 */
{ kind: "systemAppAsUser" } | 
/**
 * ⚠️ Data protected with keys tied to the source phone (point 18).
 */
{ kind: "keystore" } | 
/**
 * ⚠️ The target has a newer version; only data is restored onto it.
 */
{ kind: "installedNewer"; installed: number; backup: number } | 
/**
 * ⚠️ It will become the default for a role another app holds now.
 */
{ kind: "roleTaken"; role: string; holder: string }
/**
 * Everything the Restore screen shows before starting (ui-spec §4 header and tabs).
 */
export type RestorePreview = { backupPath: string; manifest: Manifest; apps: PreviewApp[]; 
/**
 * Resto tab items of the backup and what can be restored of each.
 */
other: OtherCompat[]; 
/**
 * Settings ticked when the backup was made ("table/key").
 */
savedSettings: string[]; 
/**
 * Shared-storage folders in the backup ("" = loose files).
 */
savedFolders: string[]; 
/**
 * Current default-app holders on the target, role → packages.
 */
targetRoles: Partial<{ [key in string]: string[] }> }
export type RestoreRequest = { backupPath: string; apps: RestoreSelection[]; 
/**
 * `-i com.android.vending`: the app shows as installed from Play.
 */
installAsPlay: boolean; 
/**
 * `--bypass-low-target-sdk-block` (not verified).
 */
bypassLowTargetSdk: boolean; 
/**
 * Resto tab.
 */
other?: OtherRestoreSelection }
export type RestoreSelection = { package: string; 
/**
 * Install or update the APK when the plan says so.
 */
app: boolean; data: DataPart[]; permissions: boolean; excludedPermissions?: string[] }
export type RestoredApp = { package: string; 
/**
 * UID on the target after installing (shown in advanced mode).
 */
uid: number | null; installed: boolean; dataParts: DataPart[]; 
/**
 * Permission keys (see `backup::permission_keys`) that could not be applied.
 */
failedPermissions: string[] }
/**
 * How root is obtained on the phone (backup-android.md, Contexto).
 */
export type RootMethod = 
/**
 * `su` from Magisk, KernelSU…: commands are wrapped in `su -c '…'`.
 */
"su" | 
/**
 * adbd itself runs as root (`adb root`): commands run as-is.
 */
"adbRoot"
/**
 * Result of checking root (ui-spec §2: sin root / root denegado / listo).
 */
export type RootStatus = { 
/**
 * The method in use; `None` without root.
 */
method: RootMethod | null; 
/**
 * Every method that works, for the advanced-mode choice.
 */
available: RootMethod[]; 
/**
 * `su` was found but access was refused (or the prompt timed out).
 */
suDenied: boolean; 
/**
 * e.g. "Magisk 30700", "KernelSU".
 */
suProvider: string | null }
export type SettingEntry = { table: string; key: string; value: string }
export type SettingView = { table: string; key: string; value: string; 
/**
 * Marked for restoring when the backup was made.
 */
selected: boolean }
export type SourceDevice = { serial: string; manufacturer: string; model: string; androidRelease: string; sdk: number; abis: string[]; buildType: string; buildId: string; rootMethod: RootMethod | null }
export type SpecialAccess = { kind: "notificationListener"; component: string } | { kind: "accessibility"; component: string } | 
/**
 * Enabled keyboard; `default` when it is the active one.
 */
{ kind: "inputMethod"; component: string; default: boolean } | 
/**
 * In the battery-optimization allowlist (`dumpsys deviceidle whitelist +pkg`).
 */
{ kind: "batteryUnrestricted" } | { kind: "deviceAdmin"; component: string }
export type StageError = { stage: AnalysisStage; error: CoreError }
export type Storage = { freeBytes: number; totalBytes: number }
export type Tool = { name: string; path: string | null }
export type UserEntry = { id: number; name: string; running: boolean }
/**
 * Integrity check progress (files checked of total) for a backup in "Mis copias".
 */
export type VerifyProgressEvent = { path: string; done: number; total: number }
export type VerifyReport = { filesChecked: number; problems: FileProblem[] }
export type WifiSecurity = "open" | "owe" | "wep" | "wpa2" | "wpa3" | 
/**
 * 802.1X: needs certificates and credentials that are not in the file.
 */
"enterprise"
export type WifiView = { ssid: string; security: WifiSecurity; hidden: boolean; hasPassword: boolean; 
/**
 * Only filled when asked to show the passwords.
 */
password: string | null }

/** tauri-specta globals **/

import {
	invoke as TAURI_INVOKE,
	Channel as TAURI_CHANNEL,
} from "@tauri-apps/api/core";
import * as TAURI_API_EVENT from "@tauri-apps/api/event";
import { type WebviewWindow as __WebviewWindow__ } from "@tauri-apps/api/webviewWindow";

type __EventObj__<T> = {
	listen: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.listen<T>>;
	once: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.once<T>>;
	emit: null extends T
		? (payload?: T) => ReturnType<typeof TAURI_API_EVENT.emit>
		: (payload: T) => ReturnType<typeof TAURI_API_EVENT.emit>;
};

export type Result<T, E> =
	| { status: "ok"; data: T }
	| { status: "error"; error: E };

function __makeEvents__<T extends Record<string, any>>(
	mappings: Record<keyof T, string>,
) {
	return new Proxy(
		{} as unknown as {
			[K in keyof T]: __EventObj__<T[K]> & {
				(handle: __WebviewWindow__): __EventObj__<T[K]>;
			};
		},
		{
			get: (_, event) => {
				const name = mappings[event as keyof T];

				return new Proxy((() => {}) as any, {
					apply: (_, __, [window]: [__WebviewWindow__]) => ({
						listen: (arg: any) => window.listen(name, arg),
						once: (arg: any) => window.once(name, arg),
						emit: (arg: any) => window.emit(name, arg),
					}),
					get: (_, command: keyof __EventObj__<any>) => {
						switch (command) {
							case "listen":
								return (arg: any) => TAURI_API_EVENT.listen(name, arg);
							case "once":
								return (arg: any) => TAURI_API_EVENT.once(name, arg);
							case "emit":
								return (arg: any) => TAURI_API_EVENT.emit(name, arg);
						}
					},
				});
			},
		},
	);
}
